public object FfiConverterTypeTranscriberCore: FfiConverter<TranscriberCore, Pointer> {

    override fun lower(value: TranscriberCore): Pointer {
        return value.uniffiClonePointer()
    }

    override fun lift(value: Pointer): TranscriberCore {
        return TranscriberCore(value)
    }

    override fun read(buf: ByteBuffer): TranscriberCore {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: TranscriberCore) = 8UL

    override fun write(value: TranscriberCore, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}



