/**
 * VAD configuration. Silence detection drives interval cutting.
 */
data class VadConfig (
    /**
     * Silero speech-probability threshold (0.0..1.0). Frames below count as
     * silence (subject to the RMS safety net below).
     */
    var `sileroThreshold`: kotlin.Float, 
    /**
     * RMS safety net: a frame the VAD calls "silence" is still treated as
     * speech if its normalized RMS >= this value. Ported default: 0.008.
     */
    var `rmsFallback`: kotlin.Float
) {
    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeVadConfig: FfiConverterRustBuffer<VadConfig> {
    override fun read(buf: ByteBuffer): VadConfig {
        return VadConfig(
            FfiConverterFloat.read(buf),
            FfiConverterFloat.read(buf),
        )
    }

    override fun allocationSize(value: VadConfig) = (
            FfiConverterFloat.allocationSize(value.`sileroThreshold`) +
            FfiConverterFloat.allocationSize(value.`rmsFallback`)
    )

    override fun write(value: VadConfig, buf: ByteBuffer) {
            FfiConverterFloat.write(value.`sileroThreshold`, buf)
            FfiConverterFloat.write(value.`rmsFallback`, buf)
    }
}



/**
 * Hardware acceleration hint for the ASR backend. Low resource usage is the
 * priority; `Auto` picks the cheapest capable provider per platform.
 */

enum class Acceleration {
    
    /**
     * Pick best-but-cheap automatically (CoreML/ANE on Apple, NNAPI on
     * Android, else CPU/XNNPACK).
     */
    AUTO,
    CPU,
    /**
     * Apple CoreML execution provider (uses ANE/GPU where available).
     */
    CORE_ML,
    /**
     * Generic GPU provider where the runtime supports it.
     */
    GPU;
    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypeAcceleration: FfiConverterRustBuffer<Acceleration> {
    override fun read(buf: ByteBuffer) = try {
        Acceleration.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: Acceleration) = 4UL

    override fun write(value: Acceleration, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}






