sealed class CoreException: kotlin.Exception() {
    
    class Config(
        
        val v1: kotlin.String
        ) : CoreException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class ModelLoad(
        
        val v1: kotlin.String
        ) : CoreException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class ModelDownload(
        
        val v1: kotlin.String
        ) : CoreException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class Audio(
        
        val v1: kotlin.String
        ) : CoreException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class Backend(
        
        val v1: kotlin.String
        ) : CoreException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class Store(
        
        val v1: kotlin.String
        ) : CoreException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class Api(
        
        val v1: kotlin.String
        ) : CoreException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class Internal(
        
        val v1: kotlin.String
        ) : CoreException() {
        override val message
            get() = "v1=${ v1 }"
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<CoreException> {
        override fun lift(error_buf: RustBuffer.ByValue): CoreException = FfiConverterTypeCoreError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeCoreError : FfiConverterRustBuffer<CoreException> {
    override fun read(buf: ByteBuffer): CoreException {
        

        return when(buf.getInt()) {
            1 -> CoreException.Config(
                FfiConverterString.read(buf),
                )
            2 -> CoreException.ModelLoad(
                FfiConverterString.read(buf),
                )
            3 -> CoreException.ModelDownload(
                FfiConverterString.read(buf),
                )
            4 -> CoreException.Audio(
                FfiConverterString.read(buf),
                )
            5 -> CoreException.Backend(
                FfiConverterString.read(buf),
                )
            6 -> CoreException.Store(
                FfiConverterString.read(buf),
                )
            7 -> CoreException.Api(
                FfiConverterString.read(buf),
                )
            8 -> CoreException.Internal(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: CoreException): ULong {
        return when(value) {
            is CoreException.Config -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is CoreException.ModelLoad -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is CoreException.ModelDownload -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is CoreException.Audio -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is CoreException.Backend -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is CoreException.Store -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is CoreException.Api -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is CoreException.Internal -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
        }
    }

    override fun write(value: CoreException, buf: ByteBuffer) {
        when(value) {
            is CoreException.Config -> {
                buf.putInt(1)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is CoreException.ModelLoad -> {
                buf.putInt(2)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is CoreException.ModelDownload -> {
                buf.putInt(3)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is CoreException.Audio -> {
                buf.putInt(4)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is CoreException.Backend -> {
                buf.putInt(5)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is CoreException.Store -> {
                buf.putInt(6)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is CoreException.Api -> {
                buf.putInt(7)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is CoreException.Internal -> {
                buf.putInt(8)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



