    data class StateChanged(
        val `state`: SessionState) : CoreEvent() {
        companion object
    }
    
    data class IntervalCommitted(
        val `interval`: IntervalRecord) : CoreEvent() {
        companion object
    }
    
    data class Metrics(
        val `snapshot`: MetricsSnapshot) : CoreEvent() {
        companion object
    }
    
    data class VoiceActivity(
        val `channelId`: kotlin.String, 
        val `at`: kotlin.String) : CoreEvent() {
        companion object
    }
    
    data class ModelProgress(
        val `status`: ModelStatus) : CoreEvent() {
        companion object
    }
    
    data class Error(
        val `code`: ErrorCode, 
        val `message`: kotlin.String) : CoreEvent() {
        companion object
    }
    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeCoreEvent : FfiConverterRustBuffer<CoreEvent>{
    override fun read(buf: ByteBuffer): CoreEvent {
        return when(buf.getInt()) {
            1 -> CoreEvent.StateChanged(
                FfiConverterTypeSessionState.read(buf),
                )
            2 -> CoreEvent.IntervalCommitted(
                FfiConverterTypeIntervalRecord.read(buf),
                )
            3 -> CoreEvent.Metrics(
                FfiConverterTypeMetricsSnapshot.read(buf),
                )
            4 -> CoreEvent.VoiceActivity(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            5 -> CoreEvent.ModelProgress(
                FfiConverterTypeModelStatus.read(buf),
                )
            6 -> CoreEvent.Error(
                FfiConverterTypeErrorCode.read(buf),
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: CoreEvent) = when(value) {
        is CoreEvent.StateChanged -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeSessionState.allocationSize(value.`state`)
            )
        }
        is CoreEvent.IntervalCommitted -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeIntervalRecord.allocationSize(value.`interval`)
            )
        }
        is CoreEvent.Metrics -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeMetricsSnapshot.allocationSize(value.`snapshot`)
            )
        }
