/**
 * How the engine picks the spoken language.
 */
sealed class LanguageMode {
    
    /**
     * Single backend pass in auto-detect mode.
     */
    object Auto : LanguageMode()
    
    
    /**
     * Single pass forced to this ISO code ("ru", "en", ...).
     */
    data class Fixed(
        val `code`: kotlin.String) : LanguageMode() {
        companion object
    }
    
    /**
     * Whisper-only: run several passes (e.g. auto/ru/en) and score the best.
     */
    data class Candidates(
        val `codes`: List<kotlin.String>) : LanguageMode() {
        companion object
    }
    

    
    companion object
}

/**
 * @suppress
